do $vocab$ declare data jsonb := $etf_data$[{"lesson_id": "1cf44326-a99f-5518-b92b-025ef63afd98", "lesson_slug": "mvp-etf-3-01", "name": "ETF P3 · 01 · Make Motion Travel Through a Tube", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "hydraulic", "definition": "Using a liquid to transmit pressure and motion in a connected system.", "tier": 3, "category": "project-language", "example": "A water-filled syringe pair can move a small platform from a remote hand input.", "order_index": 0, "difficulty": "medium"}, {"term": "pneumatic", "definition": "Using a gas, commonly air, to transmit pressure and produce motion.", "tier": 3, "category": "project-language", "example": "The air-filled syringe system feels springier because its air can compress.", "order_index": 1, "difficulty": "medium"}, {"term": "piston", "definition": "A moving part that fits inside a cylinder and pushes on or is pushed by the fluid.", "tier": 3, "category": "project-language", "example": "The syringe plunger moves its piston 20 mm during a measured input stroke.", "order_index": 2, "difficulty": "medium"}, {"term": "input", "definition": "The action, energy, or signal supplied to a system.", "tier": 3, "category": "project-language", "example": "Pushing the hand syringe is the input that moves the remote platform.", "order_index": 3, "difficulty": "medium"}, {"term": "output", "definition": "The action, energy, or signal a system delivers.", "tier": 3, "category": "project-language", "example": "The rising platform is the output of the connected syringe machine.", "order_index": 4, "difficulty": "medium"}, {"term": "displacement", "tier": 3, "category": "measurement", "definition": "A change in position with its direction stated.", "example": "Apply the same initial sideways displacement when comparing the braced and unbraced frames.", "order_index": 5, "difficulty": "medium"}, {"term": "measured value", "tier": 2, "category": "measurement", "definition": "A number with a unit obtained from a stated measurement method.", "example": "Record the actual tape reading of 40 3/8 in before judging whether it passes.", "order_index": 6, "difficulty": "medium"}, {"term": "uncertainty", "tier": 2, "category": "measurement", "definition": "The doubt or range associated with a measurement because tools and methods cannot give an exact value.", "example": "Identify how reaction time or a hard-to-read volume mark affects confidence in the rate.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "07a41f8e-1bf4-5efe-8026-23bfdbcdab27", "lesson_slug": "mvp-etf-3-02", "name": "ETF P3 · 02 · Build a Press, Lift, or Gate", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "piston", "definition": "A moving part that fits inside a cylinder and pushes on or is pushed by the fluid.", "tier": 3, "category": "project-language", "example": "The syringe plunger moves its piston 20 mm during a measured input stroke.", "order_index": 0, "difficulty": "medium"}, {"term": "ratio", "tier": 2, "category": "math", "definition": "A comparison of two quantities by division, with units and order stated.", "example": "A folded beam reaching 8 erasers versus 2 for the flat beam has a capacity-count ratio of 4 to 1 in that test.", "order_index": 1, "difficulty": "medium"}, {"term": "area", "tier": 2, "category": "math", "definition": "The amount of a flat surface, measured in square units; a rectangle has area length × width.", "example": "The model 4 × 6 ft display has 24 ft² of surface to cover.", "order_index": 2, "difficulty": "medium"}, {"term": "displacement", "tier": 3, "category": "measurement", "definition": "A change in position with its direction stated.", "example": "Apply the same initial sideways displacement when comparing the braced and unbraced frames.", "order_index": 3, "difficulty": "medium"}, {"term": "coordination", "tier": 2, "category": "design", "definition": "Checking that related drawings, dimensions, components, and routes work together without conflict.", "example": "Make sure the route order and positions agree in the plan, side view, and model.", "order_index": 4, "difficulty": "medium"}, {"term": "brace", "tier": 3, "category": "structures", "definition": "A member added to reduce unwanted movement or deformation of a structure.", "example": "Add a diagonal paper member to reduce the frame's sideways distortion.", "order_index": 5, "difficulty": "medium"}, {"term": "assembly drawing", "definition": "A drawing showing how components fit together to form a working object.", "tier": 3, "category": "project-language", "example": "The assembly drawing shows the actuator mounted below the moving platform.", "order_index": 6, "difficulty": "medium"}, {"term": "output", "definition": "The action, energy, or signal a system delivers.", "tier": 3, "category": "project-language", "example": "The rising platform is the output of the connected syringe machine.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "e893f81c-ca62-548f-9114-51493721e7cc", "lesson_slug": "mvp-etf-3-03", "name": "ETF P3 · 03 · Choose a Tube Route Using Flow Tests", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "flow rate", "tier": 3, "category": "math", "definition": "The volume of fluid passing a point or collected per unit time, such as mL/s.", "example": "A supplied collection of 240 mL in 12 s has a flow rate of 20 mL/s.", "order_index": 0, "difficulty": "medium"}, {"term": "volume", "tier": 2, "category": "math", "definition": "The amount of three-dimensional space occupied or contained, measured in cubic units or units such as milliliters.", "example": "Record how many milliliters are collected, using the actual reading or a clearly labeled supplied value.", "order_index": 1, "difficulty": "medium"}, {"term": "elapsed time", "tier": 2, "category": "math", "definition": "The amount of time between a stated start and finish.", "example": "Measure from the stated start of collection to its finish.", "order_index": 2, "difficulty": "medium"}, {"term": "route", "tier": 3, "category": "layout", "definition": "The planned path followed by a service, material, or moving object.", "example": "Draw the two dry model service paths before constructing their crossing.", "order_index": 3, "difficulty": "medium"}, {"term": "controlled variable", "tier": 2, "category": "investigation", "definition": "A condition deliberately kept the same to make a comparison fair.", "example": "Use the same paper allowance, support spacing, and loading method when comparing shapes.", "order_index": 4, "difficulty": "medium"}, {"term": "average rate", "tier": 2, "category": "math", "definition": "The total change in a quantity divided by the time interval over which it occurred.", "example": "A 6°C drop over 10 min is an average cooling magnitude of 0.6°C/min.", "order_index": 5, "difficulty": "medium"}, {"term": "baseline", "tier": 2, "category": "investigation", "definition": "The original or reference result used for comparison with a changed design or condition.", "example": "Use the original wrap's result as the comparison point for the revised design.", "order_index": 6, "difficulty": "medium"}, {"term": "trial", "tier": 2, "category": "investigation", "definition": "One run of a test using a recorded set of conditions.", "example": "Record each run and identify whether it used a fresh specimen or a previously loaded one.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "174d2b00-f2db-5b6d-9afb-a3125f931f76", "lesson_slug": "mvp-etf-3-04", "name": "ETF P3 · 04 · Read an Assembly Plan and Build the Device", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "assembly drawing", "definition": "A drawing showing how components fit together to form a working object.", "tier": 3, "category": "project-language", "example": "The assembly drawing shows the actuator mounted below the moving platform.", "order_index": 0, "difficulty": "medium"}, {"term": "centerline", "tier": 3, "category": "layout", "definition": "A reference line through the middle of a feature, used to locate or align it.", "example": "Mark the work area's middle line so both fixture points share one centerline.", "order_index": 1, "difficulty": "medium"}, {"term": "center spacing", "definition": "The distance between the center points or centerlines of two features.", "tier": 3, "category": "project-language", "example": "Two mounting points 3/4 in from opposite edges of an 8 1/2-in plate have 7-in center spacing.", "order_index": 2, "difficulty": "medium"}, {"term": "offset", "tier": 3, "category": "layout", "definition": "A stated distance and direction from a reference line or point to a feature.", "example": "Locate a fixture 12 in inward from the short end and state the reference edge.", "order_index": 3, "difficulty": "medium"}, {"term": "bill of materials", "tier": 3, "category": "estimating", "definition": "An itemized list of materials and components, including sizes and quantities needed for an assembly.", "example": "List paper sheets and tape segments with their sizes, quantities, and simulated prices.", "order_index": 4, "difficulty": "medium"}, {"term": "clearance", "tier": 3, "category": "layout", "definition": "The space intentionally left between a part and another surface so the part can fit or move.", "example": "Add two 1/8-in clearances to the notebook width to find the tray's inside base width.", "order_index": 5, "difficulty": "medium"}, {"term": "fabrication", "tier": 3, "category": "fabrication", "definition": "Making a part from material by operations such as marking, cutting, folding, and joining.", "example": "Mark, cut, and check the paper liner using the dimensions on your work order.", "order_index": 6, "difficulty": "medium"}, {"term": "coordination", "tier": 2, "category": "design", "definition": "Checking that related drawings, dimensions, components, and routes work together without conflict.", "example": "Make sure the route order and positions agree in the plan, side view, and model.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "c443cea2-ab16-581e-9dbb-6e2a15bc748d", "lesson_slug": "mvp-etf-3-05", "name": "ETF P3 · 05 · Make It Reliable Before Racing It", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "fault", "tier": 3, "category": "electrical", "definition": "A condition that prevents a system from operating as intended.", "example": "An open switch or a broken lead can prevent the model lamp from operating.", "order_index": 0, "difficulty": "medium"}, {"term": "diagnosis", "tier": 3, "category": "inspection", "definition": "Identifying a problem's cause by following evidence from inspection and tests.", "example": "Follow a recorded sequence of inspection and approved tests to identify which condition caused the failure.", "order_index": 1, "difficulty": "medium"}, {"term": "repair", "tier": 3, "category": "fabrication", "definition": "A correction intended to restore a part or system to its required operation.", "example": "After securing the loose actuator mount, repeat the same three-cycle test to check the repair.", "order_index": 2, "difficulty": "medium"}, {"term": "volume", "tier": 2, "category": "math", "definition": "The amount of three-dimensional space occupied or contained, measured in cubic units or units such as milliliters.", "example": "Record how many milliliters are collected, using the actual reading or a clearly labeled supplied value.", "order_index": 3, "difficulty": "medium"}, {"term": "uncertainty", "tier": 2, "category": "measurement", "definition": "The doubt or range associated with a measurement because tools and methods cannot give an exact value.", "example": "Identify how reaction time or a hard-to-read volume mark affects confidence in the rate.", "order_index": 4, "difficulty": "medium"}, {"term": "access", "tier": 3, "category": "design", "definition": "The space or opening needed to reach a part for operation, inspection, or maintenance.", "example": "Demonstrate that the chosen opening lets a person reach the model component without tearing the enclosure.", "order_index": 5, "difficulty": "medium"}, {"term": "coordination", "tier": 2, "category": "design", "definition": "Checking that related drawings, dimensions, components, and routes work together without conflict.", "example": "Make sure the route order and positions agree in the plan, side view, and model.", "order_index": 6, "difficulty": "medium"}, {"term": "retest", "tier": 2, "category": "investigation", "definition": "A new test after a change, using stated conditions so the results can be compared.", "example": "Test the revised wrap under the original conditions and report an inconclusive result honestly if necessary.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "b80ba8ae-94d9-51c0-82ef-a5299242253b", "lesson_slug": "mvp-etf-3-06", "name": "ETF P3 · 06 · Measure Version One", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "baseline", "tier": 2, "category": "investigation", "definition": "The original or reference result used for comparison with a changed design or condition.", "example": "Use the original wrap's result as the comparison point for the revised design.", "order_index": 0, "difficulty": "medium"}, {"term": "elapsed time", "tier": 2, "category": "math", "definition": "The amount of time between a stated start and finish.", "example": "Measure from the stated start of collection to its finish.", "order_index": 1, "difficulty": "medium"}, {"term": "trial", "tier": 2, "category": "investigation", "definition": "One run of a test using a recorded set of conditions.", "example": "Record each run and identify whether it used a fresh specimen or a previously loaded one.", "order_index": 2, "difficulty": "medium"}, {"term": "mean", "tier": 2, "category": "math", "definition": "The arithmetic average: add the values and divide by the number of values.", "example": "For equal-duration trials with rates 20, 19, and 21 mL/s, the mean rate is 20 mL/s.", "order_index": 3, "difficulty": "medium"}, {"term": "measured value", "tier": 2, "category": "measurement", "definition": "A number with a unit obtained from a stated measurement method.", "example": "Record the actual tape reading of 40 3/8 in before judging whether it passes.", "order_index": 4, "difficulty": "medium"}, {"term": "controlled variable", "tier": 2, "category": "investigation", "definition": "A condition deliberately kept the same to make a comparison fair.", "example": "Use the same paper allowance, support spacing, and loading method when comparing shapes.", "order_index": 5, "difficulty": "medium"}, {"term": "endpoint", "tier": 2, "category": "measurement", "definition": "A point that marks the beginning or end of a measured distance.", "example": "Record whether the tape ends at a desk edge or its center; those endpoints give different lengths.", "order_index": 6, "difficulty": "medium"}, {"term": "evidence", "tier": 2, "category": "investigation", "definition": "Recorded observations, measurements, or results used to support a claim.", "example": "Record what you actually observed before choosing the next diagnostic action.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "bf678ee6-8eee-5c65-b871-f36f9fa2f8ec", "lesson_slug": "mvp-etf-3-07", "name": "ETF P3 · 07 · Redesign for a Measurable Improvement", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "revision", "tier": 2, "category": "communication", "definition": "An identified change to a drawing, plan, or product that replaces an earlier version.", "example": "After checking an unclear endpoint, date the drawing and label the corrected version revision B.", "order_index": 0, "difficulty": "medium"}, {"term": "percent increase", "tier": 2, "category": "math", "definition": "The increase divided by the original value, multiplied by 100%.", "example": "A 15% increase on a fictional $80 estimate adds $12 and gives a revised total of $92.", "order_index": 1, "difficulty": "medium"}, {"term": "percent reduction", "tier": 2, "category": "math", "definition": "The decrease divided by the original value, multiplied by 100%.", "example": "A drop reduced from 8°C to 6°C is 2/8 × 100% = 25% smaller than the original drop.", "order_index": 2, "difficulty": "medium"}, {"term": "baseline", "tier": 2, "category": "investigation", "definition": "The original or reference result used for comparison with a changed design or condition.", "example": "Use the original wrap's result as the comparison point for the revised design.", "order_index": 3, "difficulty": "medium"}, {"term": "average rate", "tier": 2, "category": "math", "definition": "The total change in a quantity divided by the time interval over which it occurred.", "example": "A 6°C drop over 10 min is an average cooling magnitude of 0.6°C/min.", "order_index": 4, "difficulty": "medium"}, {"term": "retest", "tier": 2, "category": "investigation", "definition": "A new test after a change, using stated conditions so the results can be compared.", "example": "Test the revised wrap under the original conditions and report an inconclusive result honestly if necessary.", "order_index": 5, "difficulty": "medium"}, {"term": "controlled variable", "tier": 2, "category": "investigation", "definition": "A condition deliberately kept the same to make a comparison fair.", "example": "Use the same paper allowance, support spacing, and loading method when comparing shapes.", "order_index": 6, "difficulty": "medium"}, {"term": "limitation", "tier": 2, "category": "investigation", "definition": "A boundary on what a method, model, or result can establish.", "example": "Explain which real-system tests were not performed on the paper prototype.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "ca3689a7-16a9-52de-bfde-d39082b317e2", "lesson_slug": "mvp-etf-3-08", "name": "ETF P3 · 08 · Demonstrate and Explain the Improvement", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "assembly drawing", "definition": "A drawing showing how components fit together to form a working object.", "tier": 3, "category": "project-language", "example": "The assembly drawing shows the actuator mounted below the moving platform.", "order_index": 0, "difficulty": "medium"}, {"term": "input", "definition": "The action, energy, or signal supplied to a system.", "tier": 3, "category": "project-language", "example": "Pushing the hand syringe is the input that moves the remote platform.", "order_index": 1, "difficulty": "medium"}, {"term": "output", "definition": "The action, energy, or signal a system delivers.", "tier": 3, "category": "project-language", "example": "The rising platform is the output of the connected syringe machine.", "order_index": 2, "difficulty": "medium"}, {"term": "acceptance criterion", "tier": 3, "category": "inspection", "definition": "A measurable requirement or stated test used to decide whether the work meets the job's needs.", "example": "One criterion is that a partner can locate both divider centers from your drawing without guessing.", "order_index": 3, "difficulty": "medium"}, {"term": "mean", "tier": 2, "category": "math", "definition": "The arithmetic average: add the values and divide by the number of values.", "example": "For equal-duration trials with rates 20, 19, and 21 mL/s, the mean rate is 20 mL/s.", "order_index": 4, "difficulty": "medium"}, {"term": "handover", "tier": 3, "category": "communication", "definition": "The transfer of a completed work package and its essential information to the next person or user.", "example": "Give the next person the brief, drawings, estimate, test record, revisions, and unresolved questions.", "order_index": 5, "difficulty": "medium"}, {"term": "evidence", "tier": 2, "category": "investigation", "definition": "Recorded observations, measurements, or results used to support a claim.", "example": "Record what you actually observed before choosing the next diagnostic action.", "order_index": 6, "difficulty": "medium"}, {"term": "limitation", "tier": 2, "category": "investigation", "definition": "A boundary on what a method, model, or result can establish.", "example": "Explain which real-system tests were not performed on the paper prototype.", "order_index": 7, "difficulty": "medium"}]}, {"lesson_id": "70daddfa-7ba1-5990-b891-dcee213ccd66", "lesson_slug": "mvp-etf-3-09", "name": "ETF P3 · 09 · Workshop: Troubleshoot a Machine from Its Plan", "unit_id": "trades-etf-3", "description": "Eight words for this project meeting. Preview three or four at the bench; assign the full set or a selection for review. Practical skills are assessed separately.", "recommended_target_slug": "etf26.p3.vocabulary", "terms": [{"term": "diagnosis", "tier": 3, "category": "inspection", "definition": "Identifying a problem's cause by following evidence from inspection and tests.", "example": "Follow a recorded sequence of inspection and approved tests to identify which condition caused the failure.", "order_index": 0, "difficulty": "medium"}, {"term": "unit conversion", "tier": 2, "category": "math", "definition": "Expressing the same quantity in another unit without changing its size.", "example": "Convert 3 ft 4 in to 40 in before adding it to another length in inches.", "order_index": 1, "difficulty": "medium"}, {"term": "displacement", "tier": 3, "category": "measurement", "definition": "A change in position with its direction stated.", "example": "Apply the same initial sideways displacement when comparing the braced and unbraced frames.", "order_index": 2, "difficulty": "medium"}, {"term": "reference line", "tier": 3, "category": "measurement", "definition": "A marked or established line used as the basis for locating or measuring other features.", "example": "Keep the same line for both readings so the difference has a valid basis.", "order_index": 3, "difficulty": "medium"}, {"term": "repair", "tier": 3, "category": "fabrication", "definition": "A correction intended to restore a part or system to its required operation.", "example": "After securing the loose actuator mount, repeat the same three-cycle test to check the repair.", "order_index": 4, "difficulty": "medium"}, {"term": "retest", "tier": 2, "category": "investigation", "definition": "A new test after a change, using stated conditions so the results can be compared.", "example": "Test the revised wrap under the original conditions and report an inconclusive result honestly if necessary.", "order_index": 5, "difficulty": "medium"}, {"term": "hydraulic", "definition": "Using a liquid to transmit pressure and motion in a connected system.", "tier": 3, "category": "project-language", "example": "A water-filled syringe pair can move a small platform from a remote hand input.", "order_index": 6, "difficulty": "medium"}, {"term": "pneumatic", "definition": "Using a gas, commonly air, to transmit pressure and produce motion.", "tier": 3, "category": "project-language", "example": "The air-filled syringe system feels springier because its air can compress.", "order_index": 7, "difficulty": "medium"}]}]$etf_data$::jsonb; item jsonb; saved jsonb; begin for item in select value from jsonb_array_elements(data) loop saved := public.save_lesson_vocabulary((item->>'lesson_id')::uuid,null,item->'terms',false); update public.vocabulary_sets set name=item->>'name',description=item->>'description',created_by='antoccic@fitchburg.k12.ma.us' where id=(saved->>'setId')::uuid; end loop; end $vocab$;
commit; select jsonb_build_object('project',3,'lessons',(select count(*) from lessons where unit_id='trades-etf-3' and not published),'vocabulary_sets',(select count(*) from vocabulary_sets where unit_id='trades-etf-3' and not published),'terms',(select count(*) from vocabulary_terms t join vocabulary_sets s on s.id=t.vocabulary_set_id where s.unit_id='trades-etf-3' and not t.archived));